-- Fakt kartochkalari orqa tomonining ruscha matni — 77-partiya:
-- Tog'ay Murod, To'maris.

UPDATE fact_cards SET detail_ru = 'Тагай Мурад родился 3 февраля 1948 года в селении Ходжасаат Денауского района Сурхандарьинской области. Настоящее его имя и фамилия — Менгноров Тагаймурад. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2354;
UPDATE fact_cards SET detail_ru = 'В 1972 году Тагай Мурад окончил факультет журналистики Ташкентского государственного университета, а позже, в 1984–1986 годах, учился на Высших литературных курсах в Москве. Он работал редактором на республиканском радио (1972–1975), литературным сотрудником в газете «Узбекистон физкультурачиси» (1976–1978) и в журнале «Фан ва турмуш» (1982–1984). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2355;
UPDATE fact_cards SET detail_ru = 'Повесть «Вечер, когда заржал конь» Тагай Мурад написал в 1979 году. Эта повесть считается одним из самых известных сочинений писателя. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2356;
UPDATE fact_cards SET detail_ru = 'Первая повесть Тагая Мурада «Звёзды горят вечно» была напечатана в 1976 году. Написал он также повести «Люди, идущие в лунном свете» (1980) и «Песня матери-Земли» (1985). За повесть «Люди, идущие в лунном свете» писатель был удостоен премии имени Ойбека. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2357;
UPDATE fact_cards SET detail_ru = 'Роман «Поля, оставшиеся от отца» Тагай Мурад написал в 1993 году. За это сочинение он получил в 1994 году Государственную премию имени Абдуллы Кадыри, а в 2001 году по роману был снят художественный фильм. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2358;
UPDATE fact_cards SET detail_ru = 'Тагай Мурад переложил на узбекский язык драму Джека Лондона «Дочь снегов» и его рассказы, а также повесть Э. Сетон-Томпсона «Мустанг-иноходец». Написал он и роман «В этом мире нельзя умереть» (год издания в источнике точно не указан). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2359;
UPDATE fact_cards SET detail_ru = 'Тагай Мурад был удостоен премии имени Ойбека за повесть «Люди, идущие в лунном свете», а в 1994 году — Государственной премии имени Абдуллы Кадыри за роман «Поля, оставшиеся от отца». В 1999 году ему было присвоено звание народного писателя Узбекистана. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2360;
UPDATE fact_cards SET detail_ru = 'Тагай Мурад умер 27 мая 2003 года в Ташкенте. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2361;

UPDATE fact_cards SET detail_ru = 'Массагеты — древний кочевой народ; они были в родстве с саками и жили в западной части Туранской земли.

Едва ли не все сведения обо мне взяты из одного источника — из сочинения греческого историка Геродота. У нашего собственного народа письменности той поры не сохранилось.

Потому рассказ обо мне — смесь свидетельства и предания. Об этом надо говорить открыто: сам Геродот в иных местах писал «как рассказывают».' WHERE id = 473;
UPDATE fact_cards SET detail_ru = 'Берега Амударьи и Кызылкум — две разные среды: у реки луга и вода, а в пустыне только колодцы.

Для кочевого народа такое устройство было удобно: часть года можно проводить в одном месте, часть в другом. Скот идёт за травой и водой, а человек — за скотом.

Свободный кочевник не значит, что нет управления. У нас был союз племён и единый правитель — для того чтобы выступить против завоевателя вместе, это было необходимо.' WHERE id = 474;
UPDATE fact_cards SET detail_ru = 'То, что правителем стала женщина, не было у нашего народа делом необычным: у массагетов и женщины умели держаться в седле и носить оружие.

Потому мой народ меня и поддержал. У многих других народов власть в таком случае перешла бы к родичу-мужчине.

Поскольку это предание, подробности неточны. Но итог известен: когда началось нашествие, войском начальствовала я, и переговоры вела тоже я.' WHERE id = 475;
UPDATE fact_cards SET detail_ru = 'Кир II был сильнейшим правителем своего времени: он покорил Мидию, Лидию и Вавилон и построил огромную державу.

Наша земля должна была стать следующим краем в его списке. Северный предел беспокоен для всякой державы: степные народы не покоряются и могут напасть.

Но в степи война идёт иначе. Для большого войска главный враг здесь не воин — а расстояние, безводье и длина пути снабжения.' WHERE id = 476;
UPDATE fact_cards SET detail_ru = 'Предложение было простым: уведи своё войско назад — и мы вас не тронем.

Такое предложение не признак слабости. Напротив, оно опирается на расчёт: я знала, что цена войны будет тяжела для обеих сторон.

Кир II ответил отказом. Для правителя, одержавшего много побед, это дело обычное: долгие годы удач рождают в человеке излишнюю веру в собственную силу.' WHERE id = 477;
UPDATE fact_cards SET detail_ru = 'Геродот — греческий историк поколения после меня; его называют «отцом истории», потому что он был одним из первых авторов, изложивших события в системе.

Он не видел нас своими глазами — написанное им опирается на рассказы, услышанные в странствиях, и на сведения, полученные от других.

Потому читать его текст надо с осторожностью. Но другого источника нет: не будь Геродота, не сохранилось бы ни моего имени, ни имени моего народа.' WHERE id = 478;
UPDATE fact_cards SET detail_ru = 'Геродот особо выделил эту битву в своём сочинении — как самую страшную из всех, о которых он писал.

По его описанию, битва длилась долго и шла не в обычном порядке: сперва издали стреляли из луков, а затем начался ближний бой.

Итог оказался для завоевателя неожиданным: степной народ сумел одолеть войско огромной державы. Об этом событии широко говорили в древнем мире, и его долго помнили.' WHERE id = 479;
UPDATE fact_cards SET detail_ru = 'Гибель правителя на поле боя была в древнем мире случаем редким: царь обычно держался позади войска.

Для Кира II этот поход стал последним. Он покорил много стран, но северная степь его остановила.

После него держава снова окрепла, и последующие цари вновь ходили в эту сторону. Предание о пастухе Шираке относится как раз к одному из таких позднейших походов — ко времени Дария I.' WHERE id = 480;
UPDATE fact_cards SET detail_ru = 'Моё имя живёт двумя путями: через древний греческий текст и через нынешнюю словесность.

Из наших современных поэтесс Халима Худайбердиева написала книгу «Сказанное Томирис», посвящённую отважным женщинам. То есть мой образ работает и в нынешней поэзии.

Кроме того, моё имя встречается в школьных учебниках, в произведениях искусства и в названиях улиц.' WHERE id = 481;

UPDATE fact_cards SET detail_ru = 'Мидия, Лидия и Вавилон — три больших государства той поры; покорение каждого потребовало отдельного похода.

Потому имя Кира II в древнем мире произносили с уважением и со страхом. Войско его было намного больше нашего по численности.

Но чем больше держава, тем длиннее её предел. А защищать длинный предел — значит вести постоянную войну.' WHERE id = 1800;
UPDATE fact_cards SET detail_ru = 'Употребление бронзы и золота показывает уровень нашего ремесла: первая шла на оружие, второе — на украшения.

Копьё, лук и секира — оружие, выбранное для конного воина: оно легко и удобно в руке на коне. Тяжёлое оружие всаднику не годится.

Такие вещи встречаются и в нынешних раскопках, и они подтверждают описание Геродота. То есть здесь письменный источник и археология сходятся.' WHERE id = 1801;
UPDATE fact_cards SET detail_ru = 'Этот обычай вышел из нашего хозяйства: в кочевой жизни женщина тоже ездит верхом, пасёт скот и при нужде его защищает.

У оседлых народов труд разделён иначе, и женщина-воин там встречается редко. Потому греческие авторы описывали нас с изумлением.

Именно этот обычай и сделал моё правление делом естественным: народ привык принимать приказ от женщины.' WHERE id = 1802;
UPDATE fact_cards SET detail_ru = 'По словам Геродота, мой сын начальствовал над частью войска — то есть он был не просто царевичем, а военачальником.

Его одолели не в открытом бою, а взяли хитростью. Подробность эта важна: в предании подчёркнуто, что успех врага добыт не доблестью, а лукавством.

После этого война обрела для меня иной смысл: борьба с завоевателем соединилась с потерей в семье.' WHERE id = 1803;
UPDATE fact_cards SET detail_ru = 'Почитание солнца было широко распространено среди кочевых народов: в степи жизнь прямо зависит от солнца и времён года.

А то, что ему посвящали самого быстрого коня, показывает, насколько серьёзной была эта вера: конь считался у кочевника самым дорогим имуществом.

Такие подробности были любопытны и Геродоту. Его сочинение — не только история войн: он записал и быт народов, их верования и обычаи.' WHERE id = 1804;
UPDATE fact_cards SET detail_ru = 'В нашей истории и после меня были женщины, имевшие большое влияние в государственных делах: в пору Тимуридов к таким относятся Сароймульк-ханым и Гавхаршад-бегим.

Но моё место иное: я древнейшая правительница, чьё имя сохранилось, и войском я начальствовала сама.

Это означает две вещи: во-первых, женская власть в нашей стране не новое явление; во-вторых, память об этом сохранялась две с половиной тысячи лет.' WHERE id = 1805;
UPDATE fact_cards SET detail_ru = 'Дать имя ребёнку — самая живая форма памяти: она живёт не в книге, а в повседневной жизни людей.

Кроме того, моё имя употребляется в словесности и искусстве: мой образ встречается в стихотворных книгах, в сценических сочинениях и в изобразительном искусстве.

От события двух с половиной тысячелетней давности до имени нынешней девочки путь долгий. Его прошли одна греческая книга и народная память.' WHERE id = 1806;
